import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MiniSecurity {
    record Request(String path, Map<String, String> headers) {}

    /** Mirrors SecurityContextHolder with the default MODE_THREADLOCAL strategy. */
    static final class ContextHolder {
        private static final ThreadLocal<String> CTX = new ThreadLocal<>();
        static void set(String user) { CTX.set(user); }
        static String get() { return CTX.get(); }
        static void clear() { CTX.remove(); }
    }

    interface Filter { void doFilter(Request r, Chain chain); }

    /** Mirrors VirtualFilterChain inside FilterChainProxy: index-based delegation. */
    static final class Chain {
        private final List<Filter> filters; private final Runnable target; private int pos = 0;
        Chain(List<Filter> f, Runnable target) { this.filters = f; this.target = target; }
        void next(Request r) {
            if (pos == filters.size()) { target.run(); return; }
            filters.get(pos++).doFilter(r, this);
        }
    }
    static Filter named(String name, Filter body) {
        return (r, c) -> { System.out.println("   > " + name); body.doFilter(r, c);
                           System.out.println("   < " + name); };
    }

    static final Filter AUTHN = named("BearerTokenFilter (authentication)", (r, c) -> {
        String h = r.headers().get("Authorization");
        if (h != null && h.equals("Bearer good")) ContextHolder.set("alice");
        c.next(r);
    });

    static final Filter AUTHZ = named("AuthorizationFilter", (r, c) -> {
        if (ContextHolder.get() == null) {
            System.out.println("   ! no Authentication in context -> denied (anonymous): 401");
            return;                                       // chain is cut: target never runs
        }
        c.next(r);
    });

    static final Filter CLEANUP = named("SecurityContextHolderFilter", (r, c) -> {
        try { c.next(r); } finally { ContextHolder.clear(); }
    });

    static void run(String title, List<Filter> filters, Request req) {
        System.out.println(title + "  " + req.path() + " headers=" + req.headers());
        new Chain(filters, () -> System.out.println("   => controller runs, user="
                + ContextHolder.get()))
            .next(req);
        System.out.println();
    }

    public static void main(String[] args) throws Exception {
        Request withToken = new Request("/orders", Map.of("Authorization", "Bearer good"));
        run("Correct order:", List.of(CLEANUP, AUTHN, AUTHZ), withToken);
        run("Wrong order (custom filter after AuthorizationFilter):", List.of(CLEANUP, AUTHZ,
                AUTHN), withToken);

        // thread-local does not cross to worker threads
        ContextHolder.set("alice");
        ExecutorService pool = Executors.newSingleThreadExecutor();
        String seen = pool.submit(() -> "worker thread sees user=" + ContextHolder.get()).get();
        pool.shutdown();
        System.out.println("request thread sees user=" + ContextHolder.get());
        System.out.println(seen);
        ContextHolder.clear();
    }
}

import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
public class Pbkdf2Timing {
    static byte[] pbkdf2(char[] pw, byte[] salt, int iterations) throws Exception {
        PBEKeySpec spec = new PBEKeySpec(pw, salt, iterations, 256);
        SecretKeyFactory f = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        return f.generateSecret(spec).getEncoded();
    }

    public static void main(String[] args) throws Exception {
        char[] password = "correct horse battery".toCharArray();
        byte[] salt = new byte[16];
        new SecureRandom().nextBytes(salt);
        // warm-up so that JIT compilation does not distort the first row
        for (int i = 0; i < 30; i++) pbkdf2(password, salt, 100_000);

        System.out.printf("%-12s %-12s%n", "iterations", "ms per hash (best of 11)");
        for (int it : new int[] {1_000, 10_000, 100_000, 310_000, 600_000}) {
            double ms = Double.MAX_VALUE;
            for (int r = 0; r < 11; r++) {
                long t0 = System.nanoTime();
                pbkdf2(password, salt, it);
                ms = Math.min(ms, (System.nanoTime() - t0) / 1e6);
            }
            System.out.printf("%-12d %-12.1f%n", it, ms);
        }

        // same password, different salt => different hash
        byte[] salt2 = new byte[16];
        new SecureRandom().nextBytes(salt2);
        String h1 = Base64.getEncoder().encodeToString(pbkdf2(password, salt, 10_000));
        String h2 = Base64.getEncoder().encodeToString(pbkdf2(password, salt2, 10_000));
        System.out.println("same salt, same hash      : "
            + h1.equals(Base64.getEncoder().encodeToString(pbkdf2(password, salt, 10_000))));
        System.out.println("different salt, same hash : " + h1.equals(h2));

        // constant-time comparison
        byte[] a = pbkdf2(password, salt, 10_000);
        byte[] b = pbkdf2("wrong".toCharArray(), salt, 10_000);
        System.out.println("MessageDigest.isEqual ok  : " + MessageDigest.isEqual(a, a));
        System.out.println("MessageDigest.isEqual bad : " + MessageDigest.isEqual(a, b));

        // brute-force budget at the measured cost
        long t0 = System.nanoTime();
        int n = 20;
        for (int i = 0; i < n; i++) pbkdf2(("guess" + i).toCharArray(), salt, 310_000);
        double perGuess = (System.nanoTime() - t0) / 1e9 / n;
        System.out.printf("guesses per second per core at 310000 iterations: %.1f%n", 1 / perGuess);
        long t1 = System.nanoTime();
        for (int i = 0; i < 200000; i++) MessageDigest.getInstance("SHA-256").digest(("guess"
                + i).getBytes());
        double perSha = (System.nanoTime() - t1) / 1e9 / 200000;
        System.out.printf("guesses per second per core with one plain SHA-256: %.0f%n", 1 / perSha);
    }
}

package com.example.shop.user;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.HashSet;
import java.util.Set;

@Entity
@Table(name = "app_user")
public class AppUser {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, unique = true, length = 60)
    private String username;

    @Column(name = "password_hash", nullable = false, length = 120)
    private String passwordHash;

    @Column(nullable = false)
    private boolean enabled = true;

    @Column(name = "locked_until")
    private Instant lockedUntil;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "app_user_role", joinColumns = @JoinColumn(name = "user_id"))
    @Column(name = "role", length = 30)
    private Set<String> roles = new HashSet<>();

    protected AppUser() {
    }

    public AppUser(String username, String passwordHash, Set<String> roles) {
        this.username = username;
        this.passwordHash = passwordHash;
        this.roles = new HashSet<>(roles);
    }

    public boolean isLockedAt(Instant now) {
        return lockedUntil != null && now.isBefore(lockedUntil);
    }
    // getters and setters for username, passwordHash, enabled, lockedUntil, roles
}

