import java.util.HashMap;
import java.util.Map;

public class BruteForce {
    record Attempt(int failures, long lockedUntilMs) {}

    static final Map<String, Attempt> state = new HashMap<>();
    static final int MAX_FAILURES = 5;
    static final long BASE_LOCK_MS = 1000;

    static String login(String user, String password, long now) {
        Attempt a = state.getOrDefault(user, new Attempt(0, 0));
        if (now < a.lockedUntilMs()) return "LOCKED for another " + (a.lockedUntilMs() - now)
                + " ms";
        if (password.equals("s3cret!")) {
            state.remove(user);
            return "OK";
        }
        int f = a.failures() + 1;
        long lock = f >= MAX_FAILURES ? BASE_LOCK_MS << (f - MAX_FAILURES) : 0;   // 1 s, 2 s,
                4 s ...
        state.put(user, new Attempt(f, lock > 0 ? now + lock : 0));
        return "BAD CREDENTIALS (failure " + f + (lock > 0 ? ", lock " + lock + " ms" : "") + ")";
    }

    public static void main(String[] args) {
        long now = 0;
        String[] guesses = {"123456", "password", "qwerty", "letmein", "admin", "s3cret!",
                "s3cret!",
                            "iloveyou", "monkey"};
        for (String g : guesses) {
            System.out.printf("t=%5d ms  try %-9s -> %s%n", now, g, login("alice", g, now));
            now += 200;
        }
        now += 1500;
        System.out.printf("t=%5d ms  try %-9s -> %s%n", now, "s3cret!", login("alice", "s3cret!",
                now));
    }
}

@Component
class LoginAttemptListener {

    private final LoginAttemptService attempts;

    LoginAttemptListener(LoginAttemptService attempts) {
        this.attempts = attempts;
    }

    @EventListener
    void onFailure(AuthenticationFailureBadCredentialsEvent e) {
        attempts.recordFailure(e.getAuthentication().getName());
    }

    @EventListener
    void onSuccess(AuthenticationSuccessEvent e) {
        attempts.reset(e.getAuthentication().getName());
    }
}

import java.util.List;
import java.util.Set;
import java.util.function.Predicate;

public class RuleMatcher {
    record Rule(String pattern, Predicate<Set<String>> access, String description) {}

    /** Authorities of the caller; ROLE_ADMIN implies ROLE_USER (role hierarchy). */
    static Set<String> expand(Set<String> granted) {
        if (granted.contains("ROLE_ADMIN")) {
            var all = new java.util.HashSet<>(granted);
            all.add("ROLE_USER");
            return all;
        }
        return granted;
    }

    static boolean matches(String pattern, String path) {
        if (pattern.equals("/**")) return true;
        if (pattern.endsWith("/**")) {
            return path.startsWith(pattern.substring(0, pattern.length() - 3));
        }
        return pattern.equals(path);
    }

    /** hasRole("X") is hasAuthority("ROLE_X"). */
    static Predicate<Set<String>> hasRole(String role) {
        String authority = "ROLE_" + role;
        return a -> a.contains(authority);
    }

    static String decide(List<Rule> rules, String path, Set<String> granted, boolean anonymous) {
        Set<String> a = expand(granted);
        for (Rule r : rules) {
            if (matches(r.pattern(), path)) {
                boolean ok = r.access().test(a);
                String outcome = ok ? "200 allowed"
                    : anonymous ? "401 (entry point)" : "403 (denied handler)";
                return outcome + "   [first match: " + r.pattern() + " " + r.description() + "]";
            }
        }
        return "no rule";
    }

    public static void main(String[] args) {
        List<Rule> correct = List.of(
            new Rule("/public/**", a -> true, "permitAll"),
            new Rule("/admin/**", hasRole("ADMIN"), "hasRole(ADMIN)"),
            new Rule("/**", a -> a.stream().anyMatch(x -> x.startsWith("ROLE_")), "authenticated"));
        List<Rule> wrongOrder = List.of(
            new Rule("/**", a -> a.stream().anyMatch(x -> x.startsWith("ROLE_")), "authenticated"),
            new Rule("/admin/**", hasRole("ADMIN"), "hasRole(ADMIN)"));

        Set<String> anon = Set.of();
        Set<String> user = Set.of("ROLE_USER");
        Set<String> admin = Set.of("ROLE_ADMIN");
        Set<String> unprefixed = Set.of("ADMIN");   // authority mapped from a token claim

        System.out.println("-- correct order");
        System.out.println("anonymous  /admin/users : "
            + decide(correct, "/admin/users", anon, true));
        System.out.println("USER       /admin/users : "
            + decide(correct, "/admin/users", user, false));
        System.out.println("ADMIN      /admin/users : "
            + decide(correct, "/admin/users", admin, false));
        System.out.println("USER       /orders      : "
            + decide(correct, "/orders", user, false));
        System.out.println("-- /** placed before /admin/**");
        System.out.println("USER       /admin/users : "
            + decide(wrongOrder, "/admin/users", user, false));
        System.out.println("-- authority ADMIN (no prefix) against hasRole(ADMIN)");
        System.out.println("ADMIN      /admin/users : "
            + decide(correct, "/admin/users", unprefixed, false));
    }
}

package com.example.shop.order;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

@Entity
@Table(name = "orders")
public class Order {

    public enum Status { NEW, PAID, SHIPPED, CANCELLED }

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, updatable = false, length = 60)
    private String owner;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal total;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private Status status = Status.NEW;
    protected Order() {
    }

    public Order(String owner, BigDecimal total) {
        this.owner = owner;
        this.total = total;
    }

    public void cancel() {
        if (status != Status.NEW) {
            throw new IllegalStateException("only NEW orders can be cancelled");
        }
        status = Status.CANCELLED;
    }

    // getters: getId, getOwner, getTotal, getStatus
}

