package com.example.shop.order;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService {

    public record OrderView(long id, String owner, BigDecimal total, String status) {
        static OrderView of(Order o) {
            return new OrderView(o.getId(), o.getOwner(), o.getTotal(), o.getStatus().name());
        }
    }

    private final OrderRepository orders;

    public OrderService(OrderRepository orders) {
        this.orders = orders;
    }

    @PreAuthorize("hasRole('ADMIN')")
    @Transactional(readOnly = true)
    public List<OrderView> listAll() {
        return orders.findAll().stream().map(OrderView::of).toList();
    }

    @PreAuthorize("hasRole('USER')")
    @Transactional(readOnly = true)
    public List<OrderView> listMine() {
        String me = currentUser().getName();
        return orders.findByOwnerOrderByIdDesc(me).stream().map(OrderView::of).toList();
    }

    @PreAuthorize("hasRole('USER')")
    @Transactional(readOnly = true)
    public OrderView get(long id) {
        Authentication a = currentUser();
        boolean admin = a.getAuthorities().stream()
                .anyMatch(g -> g.getAuthority().equals("ROLE_ADMIN"));
        return (admin ? orders.findById(id) : orders.findByIdAndOwner(id, a.getName()))
                .map(OrderView::of)
                .orElseThrow(() -> new OrderNotFoundException(id));
    }

    @PreAuthorize("@orderAuthz.canCancel(#id, authentication)")
    @Transactional
    public void cancel(long id) {
        orders.findById(id).orElseThrow(() -> new OrderNotFoundException(id)).cancel();
    }

    private static Authentication currentUser() {
        return SecurityContextHolder.getContext().getAuthentication();
    }
}

