    public OrderNotFoundException(long id) {
        super("order " + id + " not found");
    }
}

package com.example.shop.order;

import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component("orderAuthz")
public class OrderAuthz {

    private final OrderRepository orders;

    public OrderAuthz(OrderRepository orders) {
        this.orders = orders;
    }

    @Transactional(readOnly = true)
    public boolean canCancel(long id, Authentication auth) {
        boolean admin = auth.getAuthorities().stream()
                .anyMatch(g -> g.getAuthority().equals("ROLE_ADMIN"));
        return orders.findById(id)
                .map(o -> admin || o.getOwner().equals(auth.getName()))
                .orElse(true);   // unknown id: let the service answer 404, not 403
    }
}

