import java.util.LinkedHashMap;
import java.util.Map;

public class TokenBucketDemo {
    /** Token bucket with an injectable clock (milliseconds) so that the run is deterministic. */
    static final class TokenBucket {
        private final long capacity;
        private final double refillPerMs;
        private double tokens;
        private long lastMs;

        TokenBucket(long capacity, double refillPerSecond, long nowMs) {
            this.capacity = capacity;
            this.refillPerMs = refillPerSecond / 1000.0;
            this.tokens = capacity;
            this.lastMs = nowMs;
        }

        synchronized boolean tryAcquire(long nowMs) {
            tokens = Math.min(capacity, tokens + (nowMs - lastMs) * refillPerMs);
            lastMs = nowMs;
            if (tokens >= 1.0) {
                tokens -= 1.0;
                return true;
            }
            return false;
        }

        synchronized long retryAfterMs() {
            return (long) Math.ceil((1.0 - tokens) / refillPerMs);
        }
    }

    public static void main(String[] args) {
        // 5 requests/second sustained, burst of 10, one bucket per client key
        Map<String, TokenBucket> buckets = new LinkedHashMap<>();
        int allowed = 0, rejected = 0;
        System.out.println("client A sends 40 requests, one every 50 ms (20 req/s) for 2 s");
        for (int i = 0; i < 40; i++) {
            long now = i * 50L;
            TokenBucket b = buckets.computeIfAbsent("A", k -> new TokenBucket(10, 5, now));
            boolean ok = b.tryAcquire(now);
            if (ok) allowed++; else rejected++;
            if (i < 2 || (i >= 9 && i <= 14) || i % 10 == 0) {
                System.out.printf("t=%4d ms  request %2d  %s%s%n", now, i + 1, ok ? "200" : "429",
                    ok ? "" : "  Retry-After ~" + b.retryAfterMs() + " ms");
            }
        }
        System.out.println("allowed=" + allowed + " rejected=" + rejected);
        System.out.println("expected allowed = burst 10 + 5 req/s * 1.95 s = about 19");

        TokenBucket other = buckets.computeIfAbsent("B", k -> new TokenBucket(10, 5, 2000));
        System.out.println("client B first request at t=2000 ms: " + (other.tryAcquire(2000)
                ? "200" : "429")
            + "  (buckets are independent per key)");
    }
}

