import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.function.Supplier;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler;
import org.springframework.security.web.csrf.CsrfTokenRequestHandler;
import org.springframework.security.web.csrf.XorCsrfTokenRequestAttributeHandler;
import org.springframework.util.StringUtils;

/** Plain token from the X-XSRF-TOKEN header, masked token from rendered forms. */
final class SpaCsrfTokenRequestHandler implements CsrfTokenRequestHandler {

    private final CsrfTokenRequestHandler plain = new CsrfTokenRequestAttributeHandler();
    private final CsrfTokenRequestHandler xor = new XorCsrfTokenRequestAttributeHandler();

    @Override
    public void handle(HttpServletRequest request, HttpServletResponse response,
                       Supplier<CsrfToken> csrfToken) {
        this.xor.handle(request, response, csrfToken);
        csrfToken.get();   // forces the deferred token to load, which writes the cookie
    }

    @Override
    public String resolveCsrfTokenValue(HttpServletRequest request, CsrfToken csrfToken) {
        String header = request.getHeader(csrfToken.getHeaderName());
        return (StringUtils.hasText(header) ? this.plain : this.xor)
                .resolveCsrfTokenValue(request, csrfToken);
    }
}

package com.example.shop.security;

import java.time.Duration;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class RateLimiter {

    static final class Bucket {
        private final long capacity;
        private final double refillPerNano;
        private double tokens;
        private long lastNanos;
        private volatile long lastUsedNanos;

        Bucket(long capacity, double perSecond, long now) {
            this.capacity = capacity;
            this.refillPerNano = perSecond / 1_000_000_000.0;
            this.tokens = capacity;
            this.lastNanos = now;
            this.lastUsedNanos = now;
        }

        synchronized boolean tryAcquire(long now) {
            tokens = Math.min(capacity, tokens + (now - lastNanos) * refillPerNano);
            lastNanos = now;
            lastUsedNanos = now;
            if (tokens >= 1.0) {
                tokens -= 1.0;
                return true;
            }
            return false;
        }

        synchronized long retryAfterSeconds() {
            return Math.max(1, (long) Math.ceil((1.0 - tokens) / (refillPerNano * 1e9)));
        }
    }

    private final ConcurrentMap<String, Bucket> buckets = new ConcurrentHashMap<>();
    private static final long CAPACITY = 10;
    private static final double PER_SECOND = 5;

    /** Returns 0 when the request is allowed, otherwise the number of seconds to wait. */
    public long check(String key) {
        long now = System.nanoTime();
        Bucket b = buckets.computeIfAbsent(key, k -> new Bucket(CAPACITY, PER_SECOND, now));
        return b.tryAcquire(now) ? 0 : b.retryAfterSeconds();
    }

    @Scheduled(fixedDelay = 60_000)
    void evictIdle() {
        long cutoff = System.nanoTime() - Duration.ofMinutes(10).toNanos();
        buckets.values().removeIf(b -> b.lastUsedNanos - cutoff < 0);
    }
}

package com.example.shop.security;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.springframework.http.MediaType;
import org.springframework.web.filter.OncePerRequestFilter;

/** Not a Spring bean: constructed in the security configuration. */
public class RateLimitFilter extends OncePerRequestFilter {

    private final RateLimiter limiter;

    public RateLimitFilter(RateLimiter limiter) {
        this.limiter = limiter;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !(request.getRequestURI().equals("/login")
                || request.getRequestURI().startsWith("/api/auth/"));
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        long wait = limiter.check(request.getRemoteAddr());   // see forward-headers-strategy
        if (wait == 0) {
            chain.doFilter(request, response);
            return;
        }
        response.setStatus(429);
        response.setHeader("Retry-After", Long.toString(wait));
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        response.getWriter().write("{\"error\":\"too_many_requests\"}");
    }
}

