import java.nio.charset.StandardCharsets;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.MessageDigest;
import java.security.PublicKey;
import java.security.Signature;
import java.time.Instant;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class MiniJwt {
    static final Base64.Encoder B64 = Base64.getUrlEncoder().withoutPadding();
    static final Base64.Decoder UNB64 = Base64.getUrlDecoder();

    static String b64(byte[] b) { return B64.encodeToString(b); }
    static String b64(String s) { return b64(s.getBytes(StandardCharsets.UTF_8)); }
    static String text(String part) { return new String(UNB64.decode(part),
            StandardCharsets.UTF_8); }

    static byte[] hmac(byte[] key, String data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(key, "HmacSHA256"));
        return mac.doFinal(data.getBytes(StandardCharsets.US_ASCII));
    }

    static String signHs256(String payloadJson, byte[] key) throws Exception {
        String signingInput = b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}") + "." + b64(payloadJson);
        return signingInput + "." + b64(hmac(key, signingInput));
    }
static String signRs256(String payloadJson, KeyPair kp) throws Exception {
    String signingInput = b64("{\"alg\":\"RS256\",\"typ\":\"JWT\"}") + "." + b64(payloadJson);
    Signature s = Signature.getInstance("SHA256withRSA");
    s.initSign(kp.getPrivate());
    s.update(signingInput.getBytes(StandardCharsets.US_ASCII));
    return signingInput + "." + b64(s.sign());
}

/** Flat-JSON claim reader, sufficient for this demonstration only. */
static String claim(String json, String name) {
    Matcher m = Pattern.compile("\"" + name + "\"\\s*:\\s*(\"([^\"]*)\"|[0-9]+)").matcher(json);
    if (!m.find()) return null;
    return m.group(2) != null ? m.group(2) : m.group(1);
}

/** VULNERABLE: trusts the alg header supplied by the token. */
static String verifyNaive(String token, byte[] hmacKey, PublicKey rsaPub) throws Exception {
    String[] p = token.split("\\.", -1);
    String alg = claim(text(p[0]), "alg");
    String signingInput = p[0] + "." + p[1];
    switch (alg) {
        case "none": return text(p[1]);
        case "HS256":
            byte[] key = hmacKey != null ? hmacKey : rsaPub.getEncoded();
            if (MessageDigest.isEqual(hmac(key, signingInput),
                    UNB64.decode(p[2]))) return text(p[1]);
            break;
        case "RS256":
            Signature s = Signature.getInstance("SHA256withRSA");
            s.initVerify(rsaPub);
            s.update(signingInput.getBytes(StandardCharsets.US_ASCII));
            if (s.verify(UNB64.decode(p[2]))) return text(p[1]);
            break;
        default:
    }
    throw new SecurityException("bad signature");
}

/** STRICT: fixed algorithm, time claims checked with a clock skew allowance. */
static String verifyStrictHs256(String token, byte[] key, Instant now, long skewSeconds)
        throws Exception {
    String[] p = token.split("\\.", -1);
    if (p.length != 3) throw new SecurityException("malformed");
    if (!"HS256".equals(claim(text(p[0]),
            "alg"))) throw new SecurityException("alg not allowed");
    if (!MessageDigest.isEqual(hmac(key, p[0] + "." + p[1]), UNB64.decode(p[2])))
        throw new SecurityException("signature mismatch");
    String json = text(p[1]);
    long exp = Long.parseLong(claim(json, "exp"));
    if (now.getEpochSecond() > exp + skewSeconds) throw new SecurityException("expired");
    String nbf = claim(json, "nbf");
    if (nbf != null && now.getEpochSecond() + skewSeconds < Long.parseLong(nbf))
        throw new SecurityException("not yet valid");
    if (!"https://auth.example.com".equals(claim(json,
            "iss"))) throw new SecurityException("issuer");
    return json;
}

static void attempt(String label, java.util.concurrent.Callable<String> c) {
    try { String r = c.call();
        System.out.println(label + " -> ACCEPTED sub=" + claim(r, "sub") + " role=" + claim(r,
                "role")); }
    catch (Exception e) { System.out.println(label + " -> rejected: " + e.getMessage()); }
}

public static void main(String[] args) throws Exception {
    byte[] key = "0123456789abcdef0123456789abcdef".getBytes(StandardCharsets.UTF_8);
    Instant now = Instant.ofEpochSecond(1_800_000_000L);
    String payload = "{\"iss\":\"https://auth.example.com\",\"sub\":\"u-1001\","
        + "\"role\":\"USER\",\"iat\":" + now.getEpochSecond() + ",\"exp\":"
                + (now.getEpochSecond() + 900) + "}";

    String token = signHs256(payload, key);
    String[] p = token.split("\\.");
    System.out.println("token parts    : " + p[0].length() + " + " + p[1].length() + " + "
                + p[2].length() + " characters");
        System.out.println("token         : " + token.substring(0, 36) + "...");
        System.out.println("header        : " + text(p[0]));
        System.out.println("payload       : " + text(p[1]).replace(",\"iat",
                ",\n                \"iat"));
        System.out.println("signature len : " + UNB64.decode(p[2]).length + " bytes");
        System.out.println();

        System.out.println("== verification ==");
        attempt("valid token at t+0        ", () -> verifyStrictHs256(token, key, now, 30));
        attempt("valid token at t+920 (skew 30)", () -> verifyStrictHs256(token, key,
                now.plusSeconds(920), 30));
        attempt("valid token at t+931 (skew 30)", () -> verifyStrictHs256(token, key,
                now.plusSeconds(931), 30));

        System.out.println();
        System.out.println("== tampering: role USER -> ADMIN, signature unchanged ==");
        String forgedPayload = b64(text(p[1]).replace("USER", "ADMIN"));
        String tampered = p[0] + "." + forgedPayload + "." + p[2];
        attempt("strict verifier", () -> verifyStrictHs256(tampered, key, now, 30));

        System.out.println();
        System.out.println("== attack 1: alg=none ==");
        String none = b64("{\"alg\":\"none\",\"typ\":\"JWT\"}") + "." + forgedPayload + ".";
        System.out.println("forged token  : " + none.substring(0, 36) + "..."
                + none.substring(none.length() - 12));
        attempt("naive verifier ", () -> verifyNaive(none, key, null));
        attempt("strict verifier", () -> verifyStrictHs256(none, key, now, 30));

        System.out.println();
        System.out.println("== attack 2: RS256 -> HS256 algorithm confusion ==");
        KeyPairGenerator g = KeyPairGenerator.getInstance("RSA");
        g.initialize(2048);
        KeyPair kp = g.generateKeyPair();
        String legit = signRs256(payload, kp);
        attempt("legitimate RS256 token, naive verifier", () -> verifyNaive(legit, null,
                kp.getPublic()));
        // attacker knows only the public key (published at the JWKS endpoint)
        String signingInput = b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}") + "." + forgedPayload;
        String confused = signingInput + "." + b64(hmac(kp.getPublic().getEncoded(), signingInput));
        attempt("HS256 token signed with the public key, naive ", () -> verifyNaive(confused, null,
                kp.getPublic()));
        System.out.println("(a verifier fixed to RS256 would reject the header alg=HS256)");

        System.out.println();
        System.out.println("== key size ==");
        System.out.println("HS256 secret used above: " + key.length * 8
                + " bits (RFC 7518 requires at least 256)");
        System.out.println("RS256 signature length : " + UNB64.decode(legit.split("\\.")[2]).length
                + " bytes");
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class RefreshRotation {
    record Token(String family, boolean used) {}

    static final Map<String, Token> store = new HashMap<>();
    static final Set<String> revokedFamilies = new HashSet<>();
    static int counter = 0;

    static String issue(String family) {
        String id = "rt" + (++counter);
        store.put(id, new Token(family, false));
        return id;
    }

    static String refresh(String id) {
        Token t = store.get(id);
        if (t == null) return "401 unknown token";
        if (revokedFamilies.contains(t.family())) {
            return "401 family " + t.family() + " already revoked";
        }
        if (t.used()) {
            revokedFamilies.add(t.family());
            return "401 reuse detected: family " + t.family() + " revoked";
        }
        store.put(id, new Token(t.family(), true));
        return "200 issued " + issue(t.family()) + " (" + id + " is now used)";
    }

    public static void main(String[] args) {
        String rt1 = issue("login-1");
        System.out.println("login                    : issued " + rt1);
        System.out.println("client refreshes rt1     : " + refresh("rt1"));
        System.out.println("attacker replays rt1     : " + refresh("rt1"));
        System.out.println("client refreshes rt2     : " + refresh("rt2"));
        System.out.println("client logs in again     : issued " + issue("login-2"));
        System.out.println("new session refreshes rt3: " + refresh("rt3"));
    }
}

