import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.converter.RsaKeyConverters;
import org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;
import org.springframework.security.oauth2.jose.jws.SignatureAlgorithm;
import org.springframework.security.oauth2.jwt.JwtDecoder;
import org.springframework.security.oauth2.jwt.JwtEncoder;
import org.springframework.security.oauth2.jwt.JwtValidators;
import org.springframework.security.oauth2.jwt.NimbusJwtDecoder;
import org.springframework.security.oauth2.jwt.NimbusJwtEncoder;
@Configuration
@EnableConfigurationProperties(JwtProperties.class)
public class JwtConfig {

    private static RSAPublicKey publicKey(JwtProperties p) throws IOException {
        try (InputStream in = p.publicKey().getInputStream()) {
            return RsaKeyConverters.x509().convert(in);
        }
    }

    private static RSAPrivateKey privateKey(JwtProperties p) throws IOException {
        try (InputStream in = p.privateKey().getInputStream()) {
            return RsaKeyConverters.pkcs8().convert(in);
        }
    }

    @Bean
    JwtEncoder jwtEncoder(JwtProperties props) throws IOException {
        RSAKey jwk = new RSAKey.Builder(publicKey(props))
                .privateKey(privateKey(props))
                .keyID("shop-2026-10")
                .build();
        return new NimbusJwtEncoder(new ImmutableJWKSet<>(new JWKSet(jwk)));
    }

    @Bean
    JwtDecoder jwtDecoder(JwtProperties props, TokenDenyList denyList) throws IOException {
        NimbusJwtDecoder decoder = NimbusJwtDecoder.withPublicKey(publicKey(props))
                .signatureAlgorithm(SignatureAlgorithm.RS256)
                .build();
        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(
                JwtValidators.createDefaultWithIssuer(props.issuer()), denyList));
        return decoder;
    }
}

