package com.example.shop.auth;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.time.Instant;
import java.util.Base64;
import java.util.HexFormat;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class RefreshTokenService {

    public static class InvalidRefreshException extends RuntimeException {
    }

    public static class RefreshReuseException extends RuntimeException {
    }

    public record Rotation(String username, String newRefreshToken) {
    }

    private final RefreshTokenRepository repo;
    private final JwtProperties props;
    private final SecureRandom random = new SecureRandom();

    public RefreshTokenService(RefreshTokenRepository repo, JwtProperties props) {
        this.repo = repo;
        this.props = props;
    }

    @Transactional
    public String issue(String username, String familyId) {
        byte[] raw = new byte[32];
        random.nextBytes(raw);
        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(raw);
        repo.save(new RefreshToken(sha256(token), username, familyId,
                Instant.now().plus(props.refreshTtl())));
        return token;
    }

    @Transactional(noRollbackFor = RefreshReuseException.class)
    public Rotation rotate(String presented) {
        RefreshToken t = repo.findForUpdate(sha256(presented))
                .orElseThrow(InvalidRefreshException::new);
        if (t.isRevoked() || t.getExpiresAt().isBefore(Instant.now())) {
            throw new InvalidRefreshException();
        }
        if (t.isUsed()) {
            repo.revokeFamily(t.getFamilyId());       // committed despite the exception
            throw new RefreshReuseException();
        }
        t.markUsed();
        return new Rotation(t.getUsername(), issue(t.getUsername(), t.getFamilyId()));
    }

    @Transactional
    public void revokeFamilyOf(String presented) {
        repo.findForUpdate(sha256(presented)).ifPresent(t -> repo.revokeFamily(t.getFamilyId()));
    }

    private static String sha256(String value) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

package com.example.shop.auth;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.time.Duration;
import java.util.UUID;
import org.springframework.http.HttpHeaders;
import org.springframework.http.ResponseCookie;
import org.springframework.http.ResponseEntity;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.CookieValue;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    static final String COOKIE = "refresh_token";

    public record LoginRequest(@NotBlank String username, @NotBlank String password) {
    }

    public record TokenResponse(String accessToken, String tokenType, long expiresIn) {
    }

    private final AuthenticationManager authentication;
    private final UserDetailsService users;
    private final TokenService tokens;
    private final RefreshTokenService refreshTokens;
    private final TokenDenyList denyList;
    private final JwtProperties props;

    public AuthController(AuthenticationManager authentication, UserDetailsService users,
                          TokenService tokens, RefreshTokenService refreshTokens,
                          TokenDenyList denyList, JwtProperties props) {
        this.authentication = authentication;
        this.users = users;
        this.tokens = tokens;
        this.refreshTokens = refreshTokens;
        this.denyList = denyList;
        this.props = props;
    }

    @PostMapping("/login")
    public ResponseEntity<TokenResponse> login(@Valid @RequestBody LoginRequest req) {
        Authentication auth = authentication.authenticate(
                UsernamePasswordAuthenticationToken.unauthenticated(
                        req.username(), req.password()));
        String refresh = refreshTokens.issue(auth.getName(), UUID.randomUUID().toString());
        return respond(tokens.accessToken(auth.getName(), auth.getAuthorities()), refresh);
    }

    @PostMapping("/refresh")
    public ResponseEntity<TokenResponse> refresh(
            @CookieValue(name = COOKIE, required = false) String presented) {
        if (presented == null) {
            throw new RefreshTokenService.InvalidRefreshException();
        }
        RefreshTokenService.Rotation r = refreshTokens.rotate(presented);
        UserDetails user = users.loadUserByUsername(r.username());   // current roles and status
        if (!user.isEnabled() || !user.isAccountNonLocked()) {
            throw new RefreshTokenService.InvalidRefreshException();
        }
        return respond(tokens.accessToken(user.getUsername(), user.getAuthorities()),
                r.newRefreshToken());
    }

    @PostMapping("/logout")
    public ResponseEntity<Void> logout(
            @AuthenticationPrincipal Jwt jwt,
            @CookieValue(name = COOKIE, required = false) String presented) {
        if (presented != null) {
            refreshTokens.revokeFamilyOf(presented);
        }
        denyList.revoke(jwt.getId(), jwt.getExpiresAt());
        return ResponseEntity.noContent()
                .header(HttpHeaders.SET_COOKIE, cookie("", Duration.ZERO).toString())
                .build();
    }

    private ResponseEntity<TokenResponse> respond(String access, String refresh) {
        return ResponseEntity.ok()
                .header(HttpHeaders.SET_COOKIE, cookie(refresh, props.refreshTtl()).toString())
                .body(new TokenResponse(access, "Bearer", props.accessTtl().toSeconds()));
    }

    private static ResponseCookie cookie(String value, Duration maxAge) {
        return ResponseCookie.from(COOKIE, value)
                .httpOnly(true)
                .secure(true)
                .sameSite("Strict")
                .path("/api/auth")
                .maxAge(maxAge)
                .build();
    }
}

