package com.example.shop.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.annotation.Order;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.authentication.configuration
        .AuthenticationConfiguration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.oauth2.server.resource.authentication
        .JwtAuthenticationConverter;
import org.springframework.security.oauth2.server.resource.authentication
        .JwtGrantedAuthoritiesConverter;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@EnableWebSecurity
public class JwtSecurityConfig {

    @Bean
    AuthenticationManager authenticationManager(AuthenticationConfiguration cfg) throws Exception {
        return cfg.getAuthenticationManager();
    }

    @Bean
    JwtAuthenticationConverter jwtAuthenticationConverter() {
        JwtGrantedAuthoritiesConverter roles = new JwtGrantedAuthoritiesConverter();
        roles.setAuthoritiesClaimName("roles");
        roles.setAuthorityPrefix("ROLE_");
        JwtAuthenticationConverter converter = new JwtAuthenticationConverter();
        converter.setJwtGrantedAuthoritiesConverter(roles);
        return converter;
    }

    @Bean
    @Order(1)
    SecurityFilterChain apiChain(HttpSecurity http, JwtAuthenticationConverter converter)
            throws Exception {
        http.securityMatcher("/api/**")
            // bearer header only; the refresh cookie is SameSite=Strict
            .csrf(csrf -> csrf.disable())
            .cors(Customizer.withDefaults())
            .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(a -> a
                .requestMatchers("/api/auth/login", "/api/auth/refresh",
                        "/api/auth/register").permitAll()
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated())
            .oauth2ResourceServer(o -> o
                .jwt(j -> j.jwtAuthenticationConverter(converter)));
        return http.build();
    }
}

public class BearerFilter extends OncePerRequestFilter {

    private final JwtDecoder decoder;
    private final JwtAuthenticationConverter converter;
    private final AuthenticationEntryPoint entryPoint = new BearerTokenAuthenticationEntryPoint();

    public BearerFilter(JwtDecoder decoder, JwtAuthenticationConverter converter) {
        this.decoder = decoder;
        this.converter = converter;
    }
    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res,
                                    FilterChain chain) throws ServletException, IOException {
        String header = req.getHeader(HttpHeaders.AUTHORIZATION);
        if (header != null && header.startsWith("Bearer ")) {
            try {
                Jwt jwt = decoder.decode(header.substring(7));   // signature, exp, iss, deny list
                SecurityContext ctx = SecurityContextHolder.createEmptyContext();
                ctx.setAuthentication(converter.convert(jwt));
                SecurityContextHolder.setContext(ctx);
            } catch (JwtException e) {
                SecurityContextHolder.clearContext();
                entryPoint.commence(req, res, new InvalidBearerTokenException(e.getMessage(), e));
                return;
            }
        }
        chain.doFilter(req, res);
    }
}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.List;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class WeakSecret {
    static final Base64.Encoder B64 = Base64.getUrlEncoder().withoutPadding();

    static byte[] hmac(byte[] key, String data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(key, "HmacSHA256"));
        return mac.doFinal(data.getBytes(StandardCharsets.US_ASCII));
    }

    public static void main(String[] args) throws Exception {
        String header = B64.encodeToString("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes());
        String payload = B64.encodeToString("{\"sub\":\"u-1001\",\"role\":\"USER\"}".getBytes());
        String signingInput = header + "." + payload;
        // signature produced by the server with its (weak) key
        byte[] observedSignature = hmac("secret123".getBytes(), signingInput);

        // The attacker holds one token and tries candidate secrets offline.
        List<String> dictionary = List.of("password", "123456", "changeme", "secret", "jwtsecret",
            "mysecretkey", "supersecret", "secret123", "admin", "letmein");
        long t0 = System.nanoTime();
        int tries = 0;
        String found = null;
        for (String candidate : dictionary) {
            tries++;
            byte[] guess = hmac(candidate.getBytes(), signingInput);
            if (MessageDigest.isEqual(guess, observedSignature)) {
                found = candidate;
                break;
            }
        }
        System.out.println("dictionary attack: secret = " + found + " after " + tries + " guesses");

        // Throughput of an offline attack on a single CPU thread
        int n = 300_000;
        t0 = System.nanoTime();
        for (int i = 0; i < n; i++) hmac(("k" + i).getBytes(), signingInput);
        double perSec = n / ((System.nanoTime() - t0) / 1e9);
        System.out.printf("offline HMAC guesses per second on one thread: %.0f%n", perSec);

        double lower8 = Math.pow(26, 8);
        System.out.printf("8 lowercase letters : %.2e candidates, %.1f hours on one thread%n",
            lower8, lower8 / perSec / 3600);
        double bits256 = Math.pow(2, 256);
        System.out.printf("256-bit random key  : %.2e candidates, not searchable%n", bits256);
    }
}

@Bean
SecretKey hmacKey(@Value("${app.jwt.hmac-secret}") String base64Secret) {
    byte[] key = Base64.getDecoder().decode(base64Secret);
    if (key.length < 32) {
        throw new IllegalStateException("HS256 secret must be at least 256 bits");
    }
    return new SecretKeySpec(key, "HmacSHA256");
}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Pkce {
    static String s256(String verifier) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] d = md.digest(verifier.getBytes(StandardCharsets.US_ASCII));
        return Base64.getUrlEncoder().withoutPadding().encodeToString(d);
    }

    public static void main(String[] args) throws Exception {
        // RFC 7636 appendix B test vector
        String verifier = "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk";
        System.out.println("RFC 7636 verifier  : " + verifier);
        System.out.println("computed challenge : " + s256(verifier));
        System.out.println("RFC 7636 challenge : E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM");
        System.out.println("equal              : "
            + s256(verifier).equals("E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM"));

        // fresh verifier from 32 random bytes
        byte[] raw = new byte[32];
        new SecureRandom().nextBytes(raw);
        String v = Base64.getUrlEncoder().withoutPadding().encodeToString(raw);
        System.out.println("generated verifier length: " + v.length()
                + " characters (allowed 43..128)");

        // Authorization server check at the token endpoint
        String challengeStored = s256(v);
        System.out.println("token request with the right verifier : "
            + (s256(v).equals(challengeStored) ? "code accepted" : "invalid_grant"));
        System.out.println("token request by an interceptor (no verifier): "
            + (s256("guess").equals(challengeStored) ? "code accepted" : "invalid_grant"));
    }
}

