package com.example.shop.security;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.List;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.filter.OncePerRequestFilter;

/** Not a Spring bean: constructed in the security configuration. */
public class ApiKeyFilter extends OncePerRequestFilter {

    public record Client(String name, List<String> scopes, boolean active) {
    }

    public interface KeyStore {
        java.util.Optional<Client> findByDigest(String sha256Hex);
    }

    private final KeyStore keys;

    public ApiKeyFilter(KeyStore keys) {
        this.keys = keys;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !request.getRequestURI().startsWith("/partner/");
    }

    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res,
                                    FilterChain chain) throws ServletException, IOException {
        String presented = req.getHeader("X-API-Key");
        if (presented == null) {
            res.sendError(HttpServletResponse.SC_UNAUTHORIZED);
            return;
        }
        // lookup by digest: no secret comparison happens in application code
        var client = keys.findByDigest(sha256(presented)).filter(Client::active);
        if (client.isEmpty()) {
            res.sendError(HttpServletResponse.SC_UNAUTHORIZED);
            return;
        }
        var authorities = client.get().scopes().stream()
                .map(s -> new SimpleGrantedAuthority("SCOPE_" + s)).toList();
        SecurityContext ctx = SecurityContextHolder.createEmptyContext();
        ctx.setAuthentication(UsernamePasswordAuthenticationToken.authenticated(
                client.get().name(), null, authorities));
        SecurityContextHolder.setContext(ctx);
        chain.doFilter(req, res);
    }

    private static String sha256(String v) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(v.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

