                .with(jwt().authorities(new SimpleGrantedAuthority("SCOPE_orders.read"))))
                .andExpect(status().isOk());
    }

    @Test
    void tokenWithoutScopeIsForbidden() throws Exception {
        mvc.perform(post("/api/orders/1/cancel").with(jwt())).andExpect(status().isForbidden());
    }
}

@SpringBootTest
class OrderServiceSecurityTest {

    @Autowired
